package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.util.*;
public final class SkyPlanesTest {
 public static void main(String[] args)throws Exception{Path dir=Paths.get(args[0]);byte[] asset=Files.readAllBytes(dir.resolve("asset.bin")),palette=Files.readAllBytes(dir.resolve("sky-palettes.bin"));int count=0;NativeSky.Sample last=null;for(String line:Files.readAllLines(dir.resolve("planes.tsv"))){String[] x=line.split("\t");int pair=Integer.parseInt(x[0]),mode=Integer.parseInt(x[1]);NativeSky a=new NativeSky(Files.readAllBytes(dir.resolve("pair-"+pair+"-old.bin"))),b=new NativeSky(Files.readAllBytes(dir.resolve("pair-"+pair+"-new.bin")));last=a.sample(b,asset,Double.parseDouble(x[2]),mode);NativeSkyPlanes planes=new NativeSkyPlanes(last,palette);if(!SkyTest.hash(planes.lower()).equals(x[3])||!SkyTest.hash(planes.upper()).equals(x[4])||planes.weight!=last.weight||!planes.lower().isReadOnly())throw new AssertionError(line);int covered=0;ByteBuffer lo=planes.lower();for(int i=3;i<153600;i+=4)if(lo.get(i)!=0)covered++;if(covered!=15136)throw new AssertionError("sky footprint");count++;}if(count!=330)throw new AssertionError("missing planes");NativeSkyPlanes retained=new NativeSkyPlanes(last,palette);String hash=SkyTest.hash(retained.lower());Arrays.fill(palette,(byte)0);if(!hash.equals(SkyTest.hash(retained.lower())))throw new AssertionError("borrowed palette");try{new NativeSkyPlanes(last,new byte[1]);throw new AssertionError("palette size");}catch(IllegalArgumentException good){}System.out.println("PASS_SKY_PLANES_C_PARITY samples="+count+" rgba_planes="+(count*2)+" immutable=true");}
}
